-- Re-habilitar triggers
ALTER TABLE bauth.idn_roles_rol_hierarchical ENABLE TRIGGER ALL;

-- Verificación
SELECT
    'T300__idn_roles_rol_hierarchical: ' || COUNT(*) || ' roles cargados' AS resultado,
    COUNT(*) FILTER (WHERE depth = 0) AS raiz,
    COUNT(*) FILTER (WHERE tier = 'SU') AS tier_su,
    COUNT(*) FILTER (WHERE status = 'ACTIVE') AS activos
FROM bauth.idn_roles_rol_hierarchical;
